Kode Node.js CJS menggunakan axios untuk memproses permintaan GET ke `https://floader.net/php/api/api.php` dan mengembalikan hasilnya dalam format JSON adalah sebagai berikut:

```javascript
const axios = require("axios");

async function getData(url) {
  try {
    const response = await axios.get(
      `https://floader.net/php/api/api.php?url=${encodeURIComponent(url)}`,
      {
        headers: {
          "Accept": "*/*",
          "X-Requested-With": "XMLHttpRequest"
        }
      }
    );

    const htmlContent = response.data;

    const authorMatch = htmlContent.match(/Author:<a href="[^"]+" target="_blank">([^<]+)<\/a>/);
    const sdQualityMatch = htmlContent.match(/<a href="(https:\/\/video-ams2-1\.xx\.fbcdn\.net\/[^"]+\.mp4\?_nc_cat=109[^"]+)">SD quality<\/span><\/a>/);
    const hdQualityMatch = htmlContent.match(/<a href="(https:\/\/video-ams2-1\.xx\.fbcdn\.net\/[^"]+\.mp4\?_nc_cat=108[^"]+)">HD quality<\/span><\/a>/);
    const screenshotMatch = htmlContent.match(/background:url\(([^)]+)\)/);
    const durationMatch = htmlContent.match(/Download file \(([^)]+)\):/);

    const result = {
      author: authorMatch ? authorMatch[1] : null,
      sdQualityUrl: sdQualityMatch ? sdQualityMatch[1] : null,
      hdQualityUrl: hdQualityMatch ? hdQualityMatch[1] : null,
      screenshotUrl: screenshotMatch ? screenshotMatch[1] : null,
      duration: durationMatch ? durationMatch[1] : null,
      rawHtml: htmlContent
    };

    return result;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

async function processRequest(m) {
  const inputUrl = "https://www.facebook.com/share/v/1EHRaSNXih/";
  const result = await getData(inputUrl);
  m.reply(JSON.stringify(result, null, 2));
}

// Asumsi 'm' adalah objek yang memiliki metode 'reply'
// Contoh penggunaan jika Anda menjalankan ini di lingkungan yang menyediakan 'm'
